1	import { spawnSync } from "node:child_process";
2	import { findRecipe } from "@/lib/recipes";
3	import { corpusEnabled, queryRecipe, saveRecipe } from "@/lib/corpus";
4	
5	export const dynamic = "force-dynamic";
6	export const maxDuration = 300;
7	
8	// Public query endpoint, served from the Databricks lakehouse when configured.
9	//   GET /api/recipe?q=collaborative+editor           read: databricks → local corpus
10	//   GET /api/recipe?q=...&live=1                      miss: mine on-demand + write back
11	export async function GET(request: Request) {
12	  const { searchParams } = new URL(request.url);
13	  const q = searchParams.get("q") ?? "";
14	  const live = searchParams.get("live") === "1";
15	
16	  if (!q.trim()) {
17	    return Response.json(
18	      { error: "missing query", usage: "/api/recipe?q=collaborative+editor" },
19	      { status: 400 }
20	    );
21	  }
22	
23	  // 1. Databricks lakehouse (the live serving store)
24	  if (corpusEnabled()) {
25	    try {
26	      const hit = await queryRecipe(q);
27	      if (hit) return Response.json({ ...hit, source: "databricks" });
28	    } catch {
29	      // fall through to local corpus if the warehouse is unreachable
30	    }
31	  }
32	
33	  // 2. local corpus (mined + hand-authored) — always available
34	  const local = findRecipe(q);
35	  if (local) return Response.json({ ...local, source: "corpus" });
36	
37	  // 3. no hit — mine on demand?
38	  if (!live) {
39	    return Response.json(
40	      { error: "not in corpus", query: q, hint: "retry with &live=1 to mine it on-demand" },
41	      { status: 404 }
42	    );
43	  }
44	
45	  // 4. live: entire-graph engine discovers → mines → derives
46	  const res = spawnSync("node", ["engine/cli.mjs", "generate", q, "--json"], {
47	    cwd: process.cwd(),
48	    encoding: "utf8",
49	    timeout: 240000,
50	    maxBuffer: 64 * 1024 * 1024,
51	    env: { ...process.env, PATH: `${process.env.HOME}/.local/bin:${process.env.PATH}` },
52	  });
53	
54	  if (res.status !== 0 || !res.stdout?.trim()) {
55	    return Response.json(
56	      { error: "generation failed", query: q, detail: (res.stderr || "").split("\n").slice(-3).join("\n") },
57	      { status: 502 }
58	    );
59	  }
60	
61	  try {
62	    const recipe = JSON.parse(res.stdout);
63	    // write the new recipe back into the lakehouse so the corpus grows
64	    let source = "live";
65	    if (corpusEnabled()) {
66	      try {
67	        await saveRecipe(recipe);
68	        source = "live+databricks";
69	      } catch {
70	        /* keep source=live if write-back fails */
71	      }
72	    }
73	    return Response.json({ ...recipe, source });
74	  } catch {
75	    return Response.json({ error: "could not parse engine output", query: q }, { status: 502 });
76	  }
77	}
