1	// Databricks-backed recipe corpus — the lakehouse serving layer.
2	// Reads/writes workspace.recipe.recipes via the SQL Statement Execution API.
3	// If the DATABRICKS_* env vars are absent, corpusEnabled() is false and the
4	// API route falls back to the local JSON corpus.
5	import type { Recipe } from "./recipes";
6	
7	const HOST = process.env.DATABRICKS_HOST;
8	const TOKEN = process.env.DATABRICKS_TOKEN;
9	const WAREHOUSE = process.env.DATABRICKS_WAREHOUSE_ID;
10	const CATALOG = process.env.DATABRICKS_CATALOG || "workspace";
11	const SCHEMA = process.env.DATABRICKS_SCHEMA || "recipe";
12	const TABLE = `${CATALOG}.${SCHEMA}.recipes`;
13	
14	export function corpusEnabled(): boolean {
15	  return Boolean(HOST && TOKEN && WAREHOUSE);
16	}
17	
18	async function exec(statement: string) {
19	  const res = await fetch(`${HOST}/api/2.0/sql/statements`, {
20	    method: "POST",
21	    headers: {
22	      Authorization: `Bearer ${TOKEN}`,
23	      "Content-Type": "application/json",
24	    },
25	    body: JSON.stringify({
26	      warehouse_id: WAREHOUSE,
27	      statement,
28	      wait_timeout: "30s",
29	    }),
30	  });
31	  const json = await res.json();
32	  if (json.status?.state !== "SUCCEEDED") {
33	    throw new Error(json.status?.error?.message || "databricks query failed");
34	  }
35	  return json;
36	}
37	
38	// Spark SQL literals process backslash escapes — double backslashes (protect
39	// embedded JSON) then double single quotes.
40	const q = (s: string) => `'${String(s ?? "").replace(/\\/g, "\\\\").replace(/'/g, "''")}'`;
41	const arr = (a: string[]) => `array(${(a || []).map(q).join(", ")})`;
42	const asArray = (v: unknown): string[] => {
43	  try {
44	    return Array.isArray(v) ? (v as string[]) : JSON.parse(v as string);
45	  } catch {
46	    return [];
47	  }
48	};
49	const asJson = (v: unknown) => {
50	  try {
51	    return typeof v === "string" ? JSON.parse(v) : v;
52	  } catch {
53	    return [];
54	  }
55	};
56	
57	function rowToRecipe(row: string[]): Recipe {
58	  const [id, library, title, emphasis, repos, calls, runnersUp, keywords, steps, sources] = row;
59	  return {
60	    id,
61	    library,
62	    title,
63	    emphasis: emphasis || "",
64	    reposMined: Number(repos) || 0,
65	    callSites: Number(calls) || 0,
66	    runnersUp: runnersUp || "",
67	    keywords: asArray(keywords),
68	    steps: asJson(steps),
69	    sources: asArray(sources),
70	  } as Recipe;
71	}
72	
73	export async function getAllRecipes(): Promise<Recipe[]> {
74	  const r = await exec(
75	    `SELECT id, library, title, emphasis, repos_mined, call_sites, runners_up, keywords, steps, sources FROM ${TABLE}`
76	  );
77	  return (r.result?.data_array || []).map(rowToRecipe);
78	}
79	
80	// same keyword scoring as the local findRecipe, over the lakehouse rows
81	export async function queryRecipe(query: string): Promise<Recipe | null> {
82	  const qq = query.toLowerCase().trim();
83	  if (!qq) return null;
84	  let best: Recipe | null = null;
85	  let score = 0;
86	  for (const r of await getAllRecipes()) {
87	    let s = 0;
88	    for (const kw of r.keywords || []) if (qq.includes(kw)) s += kw.length;
89	    if (s > score) {
90	      score = s;
91	      best = r;
92	    }
93	  }
94	  return best;
95	}
96	
97	// write-back: upsert a freshly-generated recipe into the lakehouse
98	export async function saveRecipe(r: Recipe & { sources?: string[] }): Promise<void> {
99	  await exec(`DELETE FROM ${TABLE} WHERE id = ${q(r.id)}`);
100	  await exec(
101	    `INSERT INTO ${TABLE} VALUES (${q(r.id)}, ${q(r.library)}, ${q(r.title)}, ` +
102	      `${q(r.emphasis || "")}, ${r.reposMined || 0}, ${r.callSites || 0}, ${q(r.runnersUp || "")}, ` +
103	      `${arr(r.keywords)}, ${q(JSON.stringify(r.steps || []))}, ${arr(r.sources || [])}, 'live', current_timestamp())`
104	  );
105	}
