1	// Goal-driven, on-demand recipe generation — the real skill.
2	//
3	//   node engine/cli.mjs generate "<end goal>" [--package <pkg>] [--repos a,b,c]
4	//
5	// No hardcoded libraries. The ENGINE mines cleanly; the INTELLIGENCE
6	// (goal -> library + which repos) is best supplied by the calling agent via
7	// --package / --repos. With only a goal it falls back to best-effort discovery.
8	//
9	// Pipeline: discover repos -> mine with `entire graph edges` -> derive the
10	// playbook from the graph (top imported packages + top called library APIs),
11	// every step carrying real receipts + a real source line.
12	import { execFileSync } from "node:child_process";
13	import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
14	import { dirname, join } from "node:path";
15	import { fileURLToPath } from "node:url";
16	import { edges, importedModule } from "./graph.mjs";
17	
18	const __dirname = dirname(fileURLToPath(import.meta.url));
19	const ROOT = join(__dirname, "..");
20	const CACHE = join(__dirname, ".cache");
21	const OUT = join(ROOT, "lib", "recipes.generated.json");
22	
23	const MAX_REPOS = 3;
24	const MAX_REPO_KB = 30_000; // prefer small, focused example repos
25	
26	const PKG_DENY = new Set([
27	  "react", "react-dom", "next", "vue", "svelte", "typescript", "vite", "webpack",
28	  "eslint", "prettier", "tailwindcss", "@types/node", "@types/react",
29	  "@types/react-dom", "zod", "clsx", "classnames", "dotenv", "express",
30	  "@vitejs/plugin-react", "postcss", "autoprefixer",
31	  // icon / util noise that drowns out the real library
32	  "lucide-react", "react-icons", "@heroicons/react", "@radix-ui/react-icons",
33	  "uuid", "nanoid", "date-fns", "dayjs", "lodash", "lodash-es", "axios",
34	  "framer-motion", "@tailwindcss/vite",
35	  // UI kits — incidental to most goals, drown out the domain library
36	  "@chakra-ui/react", "@chakra-ui/icons", "@mui/material", "@mui/icons-material",
37	  "@emotion/react", "@emotion/styled", "antd", "@mantine/core", "@mantine/hooks",
38	  "bootstrap", "react-bootstrap", "@radix-ui/react-slot", "styled-components",
39	]);
40	const SYM_DENY = new Set([
41	  "useState", "useEffect", "useRef", "useMemo", "useCallback", "useContext",
42	  "useReducer", "useLayoutEffect", "useImperativeHandle", "useId", "useRouter",
43	  "useSearchParams", "usePathname", "useTheme", "useForm",
44	]);
45	
46	const sh = (cmd, args) =>
47	  execFileSync(cmd, args, { encoding: "utf8", maxBuffer: 256 * 1024 * 1024 });
48	const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
49	const repoName = (url) => url.replace(/\.git$/, "").split("/").pop();
50	const basePkg = (m) =>
51	  m.startsWith("@") ? m.split("/").slice(0, 2).join("/") : m.split("/")[0];
52	const isSource = (f) => !!f && /\.(ts|tsx|js|jsx|mjs|cjs|vue|svelte)$/.test(f);
53	
54	// ---- discovery -------------------------------------------------------------
55	function sizeOK(fullName) {
56	  try {
57	    const kb = parseInt(sh("gh", ["api", `repos/${fullName}`, "--jq", ".size"]).trim(), 10);
58	    if (kb && kb > MAX_REPO_KB) {
59	      console.error(`    skip ${fullName} (${Math.round(kb / 1000)}MB)`);
60	      return false;
61	    }
62	  } catch {}
63	  return true;
64	}
65	
66	function discoverRepos(goal, pkg) {
67	  const picked = [];
68	  const seen = new Set();
69	  try {
70	    if (pkg) {
71	      // repos that ACTUALLY import the package (grounded)
72	      console.error(`  discovering repos that import ${pkg} …`);
73	      const out = sh("gh", [
74	        "search", "code", pkg, "--language", "typescript",
75	        "--limit", "30", "--json", "repository",
76	      ]);
77	      for (const it of JSON.parse(out)) {
78	        const full = it.repository?.nameWithOwner;
79	        const url = it.repository?.url;
80	        if (!full || seen.has(full)) continue;
81	        seen.add(full);
82	        if (picked.length < MAX_REPOS && sizeOK(full)) picked.push(url);
83	      }
84	    }
85	    if (picked.length < MAX_REPOS) {
86	      console.error(`  discovering repos for "${goal}" …`);
87	      const out = sh("gh", [
88	        "search", "repos", goal, "--language", "typescript",
89	        "--sort", "stars", "--limit", "12", "--json", "fullName,url",
90	      ]);
91	      for (const r of JSON.parse(out)) {
92	        if (seen.has(r.fullName)) continue;
93	        seen.add(r.fullName);
94	        if (picked.length < MAX_REPOS && sizeOK(r.fullName)) picked.push(r.url);
95	      }
96	    }
97	  } catch (e) {
98	    console.warn("  ! discovery failed:", e.message.split("\n")[0]);
99	  }
100	  return picked;
101	}
102	
103	function clone(url) {
104	  const dest = join(CACHE, repoName(url));
105	  if (existsSync(join(dest, ".git"))) return dest;
106	  mkdirSync(CACHE, { recursive: true });
107	  console.error(`  cloning ${url} …`);
108	  try {
109	    execFileSync("git", ["clone", "--depth", "1", "--single-branch", url, dest], {
110	      stdio: ["ignore", "ignore", "ignore"], timeout: 180000,
111	    });
112	    return dest;
113	  } catch {
114	    return null;
115	  }
116	}
117	
118	// ---- helpers ---------------------------------------------------------------
119	const receipt = (repo, url, file, line) => ({
120	  label: `${repo}/${file}${line ? `:${line}` : ""}`,
121	  url: `${url}/blob/HEAD/${file}${line ? `#L${line}` : ""}`,
122	});
123	function snippet(repoPath, file, line) {
124	  if (!file || !line) return null;
125	  try {
126	    const l = readFileSync(join(repoPath, file), "utf8").split("\n")[line - 1] || "";
127	    return l.trim().slice(0, 160);
128	  } catch {
129	    return null;
130	  }
131	}
132	
133	// ---- main ------------------------------------------------------------------
134	export function generate(goal, opts = {}) {
135	  const repoUrls = opts.repos?.length ? opts.repos : discoverRepos(goal, opts.package);
136	  const repos = repoUrls
137	    .map((url) => {
138	      const path = clone(url);
139	      return path ? { url, path, name: repoName(url) } : null;
140	    })
141	    .filter(Boolean);
142	  if (!repos.length) throw new Error("no repos could be discovered/cloned for this goal");
143	
144	  for (const r of repos) {
145	    console.error(`  graphing ${r.name} …`);
146	    r.imports = edges(r.path, ["IMPORTS"]).filter((e) => isSource(e.evidence?.[0]?.file_path));
147	    r.calls = edges(r.path, ["CALLS", "CONSTRUCTS"]).filter((e) => isSource(e.evidence?.[0]?.file_path));
148	  }
149	  const total = repos.length;
150	
151	  // resolve library (agent-supplied wins; else dominant external package)
152	  const pkgRepos = new Map();
153	  const pkgReceipt = new Map();
154	  for (const r of repos) {
155	    for (const rec of r.imports) {
156	      const mod = importedModule(rec);
157	      if (!mod || mod.startsWith(".") || mod.startsWith("node:")) continue;
158	      const base = basePkg(mod);
159	      if (PKG_DENY.has(base)) continue;
160	      if (!pkgRepos.has(base)) pkgRepos.set(base, new Set());
161	      pkgRepos.get(base).add(r.name);
162	      const ev = rec.evidence?.[0];
163	      if (ev?.file_path && !pkgReceipt.has(base))
164	        pkgReceipt.set(base, receipt(r.name, r.url, ev.file_path, ev.start_line));
165	    }
166	  }
167	  const rankedPkgs = [...pkgRepos.entries()].sort((a, b) => b[1].size - a[1].size);
168	  const library = opts.package || rankedPkgs[0]?.[0] || "unknown";
169	  const famPrefix = library.startsWith("@") ? library.split("/")[0] : library;
170	  const family = rankedPkgs.filter(([p]) => p === library || p.startsWith(famPrefix));
171	  const familyPkgs = new Set(family.map(([p]) => p));
172	  if (opts.package && !familyPkgs.has(library)) familyPkgs.add(library);
173	
174	  // per-repo: which source files import the library family (co-location filter)
175	  for (const r of repos) {
176	    r.libFiles = new Set();
177	    for (const rec of r.imports) {
178	      const mod = importedModule(rec);
179	      if (!mod) continue;
180	      if (mod === library || mod.startsWith(famPrefix)) {
181	        const f = rec.evidence?.[0]?.file_path;
182	        if (f) r.libFiles.add(f);
183	      }
184	    }
185	  }
186	
187	  // ---- Install step ----
188	  const steps = [];
189	  const installPkgs = (opts.package ? [...familyPkgs] : family.map(([p]) => p));
190	  const famCounts = installPkgs.map((p) => (pkgRepos.get(p)?.size || 1));
191	  steps.push({
192	    name: "Install",
193	    freq: `${Math.max(1, ...famCounts)}/${total}`,
194	    level: "high",
195	    code: `npm i ${installPkgs.join(" ")}`,
196	    note: `Packages the mined repos import together${
197	      family.length
198	        ? `. Most common: ${family.slice(0, 3).map(([p, s]) => `${p} (${s.size}/${total})`).join(", ")}`
199	        : ""
200	    }.`,
201	    receipts: installPkgs.map((p) => pkgReceipt.get(p)).filter(Boolean).slice(0, 4),
202	  });
203	
204	  // ---- API steps: called/constructed symbols co-located with a library import
205	  const symRepos = new Map();
206	  const symReceipts = new Map();
207	  const symSnippet = new Map();
208	  for (const r of repos) {
209	    for (const rec of r.calls) {
210	      const ev = rec.evidence?.[0];
211	      if (!ev?.file_path || !r.libFiles.has(ev.file_path)) continue; // must be a library file
212	      const raw = ev.detail || (rec.to_id ? rec.to_id.split(":").pop() : "");
213	      const name = (raw || "").split(/[^A-Za-z0-9_$]+/).filter(Boolean).pop();
214	      if (!name || name.length < 3 || SYM_DENY.has(name)) continue;
215	      if (!/^[A-Z]/.test(name) && !/^use[A-Z]/.test(name)) continue;
216	      if (!symRepos.has(name)) {
217	        symRepos.set(name, new Set());
218	        symReceipts.set(name, []);
219	      }
220	      symRepos.get(name).add(r.name);
221	      const arr = symReceipts.get(name);
222	      const key = `${r.name}:${ev.file_path}:${ev.start_line}`;
223	      if (arr.length < 4 && !arr.some((x) => x._k === key)) {
224	        arr.push({ ...receipt(r.name, r.url, ev.file_path, ev.start_line), _k: key });
225	        if (!symSnippet.has(name)) {
226	          const sn = snippet(r.path, ev.file_path, ev.start_line);
227	          if (sn) symSnippet.set(name, sn);
228	        }
229	      }
230	    }
231	  }
232	  const rankedSyms = [...symRepos.entries()].sort((a, b) => b[1].size - a[1].size).slice(0, 5);
233	
234	  let callSites = installPkgs.length;
235	  for (const [name, set] of rankedSyms) {
236	    const receipts = (symReceipts.get(name) || []).map(({ _k, ...r }) => r);
237	    callSites += receipts.length;
238	    steps.push({
239	      name,
240	      freq: `${set.size}/${total}`,
241	      level: set.size >= Math.ceil(total / 2) ? "high" : "warn",
242	      code: symSnippet.get(name) || `${name}(…)`,
243	      note: `A ${library} API used across ${set.size}/${total} mined repos.`,
244	      receipts,
245	    });
246	  }
247	
248	  return {
249	    id: slug(goal),
250	    library,
251	    title: goal.charAt(0).toUpperCase() + goal.slice(1),
252	    emphasis: "",
253	    reposMined: total,
254	    callSites,
255	    runnersUp: rankedPkgs.filter(([p]) => !familyPkgs.has(p)).slice(0, 3).map(([p]) => p).join(", ") || "—",
256	    keywords: [goal.toLowerCase(), ...goal.toLowerCase().split(/\s+/)],
257	    steps,
258	    sources: repos.map((r) => r.url),
259	  };
260	}
261	
262	export function saveRecipe(recipe) {
263	  let all = [];
264	  try {
265	    all = JSON.parse(readFileSync(OUT, "utf8"));
266	  } catch {}
267	  all = all.filter((r) => r.id !== recipe.id);
268	  all.push(recipe);
269	  writeFileSync(OUT, JSON.stringify(all, null, 2));
270	}
