1	// Thin adapter over the `entire graph` CLI (entire-graph plugin).
2	// This is the ONLY place that shells out to entire-graph — swap the impl here
3	// if the CLI surface changes.
4	import { execFileSync } from "node:child_process";
5	import { existsSync } from "node:fs";
6	
7	const ENTIRE =
8	  process.env.ENTIRE_BIN ||
9	  [`${process.env.HOME}/.local/bin/entire`, "/usr/local/bin/entire", "entire"].find(
10	    (p) => p === "entire" || existsSync(p)
11	  );
12	
13	export function graphAvailable() {
14	  try {
15	    execFileSync(ENTIRE, ["graph", "capabilities", "--json"], {
16	      stdio: ["ignore", "ignore", "ignore"],
17	    });
18	    return true;
19	  } catch {
20	    return false;
21	  }
22	}
23	
24	// Stream relation records of the given types for a repo. Returns parsed
25	// { record_type:"relation", from_id, to_id, type, evidence:[{file_path,start_line,detail}] }
26	export function edges(repoPath, relations, { worktree = false } = {}) {
27	  const args = [
28	    "graph", "edges",
29	    "--repo", repoPath,
30	    "--relation", relations.join(","),
31	    "--format", "ndjson",
32	  ];
33	  if (worktree) args.push("--worktree");
34	
35	  let out = "";
36	  try {
37	    out = execFileSync(ENTIRE, args, {
38	      maxBuffer: 1024 * 1024 * 1024,
39	      encoding: "utf8",
40	      timeout: 120000, // don't let a huge repo hang the pipeline
41	    });
42	  } catch (e) {
43	    out = e.stdout ? e.stdout.toString() : "";
44	  }
45	
46	  const recs = [];
47	  for (const line of out.split("\n")) {
48	    if (!line || line[0] !== "{") continue;
49	    let obj;
50	    try {
51	      obj = JSON.parse(line);
52	    } catch {
53	      continue;
54	    }
55	    if (obj.record_type === "relation") recs.push(obj);
56	  }
57	  return recs;
58	}
59	
60	// module name from an IMPORTS edge, e.g. "external:import:@tiptap/react" -> "@tiptap/react"
61	export function importedModule(rec) {
62	  if (typeof rec.to_id === "string" && rec.to_id.startsWith("external:import:")) {
63	    return rec.to_id.slice("external:import:".length);
64	  }
65	  const ev = rec.evidence && rec.evidence[0];
66	  return ev && ev.detail ? ev.detail : null;
67	}
