1	#!/usr/bin/env node
2	// recipe — CLI entry for the integration-recipe engine (powered by entire-graph).
3	//
4	//   node engine/cli.mjs query "<what you're building>"   Find a recipe (--json for raw)
5	//   node engine/cli.mjs mine  <library>                  Re-mine a library with entire-graph
6	//   node engine/cli.mjs list                             List mined recipes
7	import { readFileSync } from "node:fs";
8	import { dirname, join } from "node:path";
9	import { fileURLToPath } from "node:url";
10	import { spawnSync } from "node:child_process";
11	import { generate, saveRecipe } from "./generate.mjs";
12	
13	const __dirname = dirname(fileURLToPath(import.meta.url));
14	const ROOT = join(__dirname, "..");
