18	  try {
19	    return JSON.parse(readFileSync(CORPUS, "utf8"));
20	  } catch {
21	    return [];
22	  }
23	}
24	
25	// same keyword scoring as the web app's findRecipe()
26	function findRecipe(query) {
27	  const q = query.toLowerCase().trim();
28	  if (!q) return null;
29	  let best = null;
30	  let score = 0;
31	  for (const r of load()) {
32	    let s = 0;
33	    for (const kw of r.keywords || []) if (q.includes(kw)) s += kw.length;
34	    if (s > score) {
35	      score = s;
36	      best = r;
37	    }
38	  }
39	  return best;
40	}
