42	function printRecipe(r) {
43	  console.log(`\n  RECIPE  ${r.library} — ${r.title} ${r.emphasis}`);
44	  console.log(
45	    `  mined from ${r.reposMined} repos · ${r.callSites} call sites · runners-up: ${r.runnersUp}\n`
46	  );
47	  r.steps.forEach((s, i) => {
48	    console.log(`  ${i + 1}. ${s.name}   [${s.level === "high" ? "✓" : "⚠"} ${s.freq} repos]`);
49	    if (s.code) console.log(s.code.split("\n").map((l) => "       " + l).join("\n"));
50	    if (s.note) console.log("     " + s.note);
51	    s.receipts.forEach((x) => console.log("       ↗ " + x.label));
52	    console.log();
53	  });
54	}
55	
56	const argv = process.argv.slice(2);
57	const cmd = argv[0];
58	const wantJson = argv.includes("--json");
59	const rest = argv.slice(1).filter((a) => a !== "--json");
60	
61	if (cmd === "query" || cmd === "recipe") {
62	  const query = rest.join(" ");
63	  const r = findRecipe(query);
64	  if (!r) {
65	    console.error(`No recipe for "${query}". See: node engine/cli.mjs list`);
66	    process.exit(1);
67	  }
68	  if (wantJson) console.log(JSON.stringify(r, null, 2));
69	  else printRecipe(r);
70	} else if (cmd === "generate" || cmd === "goal") {
71	  // goal-driven, on-demand: discover repos → mine → derive playbook
72	  const flags = {};
73	  const words = [];
74	  for (let i = 0; i < rest.length; i++) {
75	    if (rest[i] === "--repos") flags.repos = (rest[++i] || "").split(",").filter(Boolean);
76	    else if (rest[i] === "--package") flags.package = rest[++i];
77	    else words.push(rest[i]);
78	  }
79	  const goal = words.join(" ");
80	  if (!goal) {
81	    console.error('Usage: node engine/cli.mjs generate "<end goal>"');
82	    process.exit(1);
83	  }
84	  console.error(`\n▶ generating recipe for goal: "${goal}"\n`);
85	  const recipe = generate(goal, flags);
86	  saveRecipe(recipe);
87	  if (wantJson) console.log(JSON.stringify(recipe, null, 2));
88	  else {
89	    printRecipe(recipe);
90	    console.log(`  sources: ${(recipe.sources || []).join(", ")}`);
91	    console.log(`  saved to corpus as "${recipe.id}"\n`);
92	  }
93	} else if (cmd === "mine") {
94	  const res = spawnSync("node", [join(__dirname, "mine.mjs"), ...rest], { stdio: "inherit" });
95	  process.exit(res.status ?? 0);
96	} else if (cmd === "list") {
97	  const all = load();
98	  if (!all.length) console.log("No recipes yet. Run: node engine/cli.mjs mine tiptap");
99	  for (const r of all)
100	    console.log(`${r.library.padEnd(14)} ${r.title} ${r.emphasis}  (${r.reposMined} repos)`);
101	} else {
102	  console.log(`recipe — integration recipes mined from real repos (entire-graph)
103	
104	Usage:
105	  node engine/cli.mjs generate "<end goal>" [--package P] [--repos a,b]  Discover + mine + derive (add --json)
106	  node engine/cli.mjs query "<goal>"                   Search the mined corpus (instant)
107	  node engine/cli.mjs mine <library>                   Re-mine an authored library spec
108	  node engine/cli.mjs list                             List mined recipes`);
109	}
110

1	// Recipe mining engine — powered by entire-graph.
2	//
3	//   node engine/mine.mjs [library]      (default: tiptap)
4	//
5	// For each real repo that uses the library it:
6	//   1. shallow-clones it into engine/.cache
7	//   2. runs `entire graph edges` (IMPORTS / CALLS / CONSTRUCTS)
8	//   3. filters edges to the library's modules + API symbols
9	//   4. aggregates frequencies + real file:line receipts across repos
10	//   5. writes lib/recipes.generated.json for the app to serve.
11	import { execFileSync } from "node:child_process";
12	import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
13	import { dirname, join } from "node:path";
14	import { fileURLToPath } from "node:url";
15	import { LIBRARIES } from "./libraries.mjs";
16	import { edges, importedModule, graphAvailable } from "./graph.mjs";
17	
18	const __dirname = dirname(fileURLToPath(import.meta.url));
19	const ROOT = join(__dirname, "..");
20	const CACHE = join(__dirname, ".cache");
21	const OUT = join(ROOT, "lib", "recipes.generated.json");
22	
23	const repoName = (url) => url.replace(/\.git$/, "").split("/").pop();
24	const tokenize = (s) => (s || "").split(/[^A-Za-z0-9_$]+/).filter(Boolean);
25	// collapse a module path to its installable package name
26	const basePkg = (mod) =>
27	  mod.startsWith("@") ? mod.split("/").slice(0, 2).join("/") : mod.split("/")[0];
28	
29	function clone(url) {
30	  const dest = join(CACHE, repoName(url));
31	  if (existsSync(join(dest, ".git"))) return dest;
32	  mkdirSync(CACHE, { recursive: true });
33	  console.log(`  cloning ${url} …`);
34	  execFileSync(
35	    "git",
36	    ["clone", "--depth", "1", "--single-branch", url, dest],
37	    { stdio: ["ignore", "ignore", "inherit"], timeout: 180000 }
38	  );
39	  return dest;
40	}
41	
42	function receipt(repo, url, file, line) {
43	  const label = `${repo}/${file}${line ? `:${line}` : ""}`;
44	  const href = `${url}/blob/HEAD/${file}${line ? `#L${line}` : ""}`;
45	  return { label, url: href };
46	}
47	
48	function moduleMatches(mod, modules) {
49	  return modules.some((m) => mod === m || mod.startsWith(m + "/"));
50	}
51	
52	function mine(libKey) {
53	  const spec = LIBRARIES[libKey];
54	  if (!spec) throw new Error(`unknown library: ${libKey}`);
55	
56	  const repos = spec.repos.map((url) => {
57	    try {
58	      return { url, path: clone(url), name: repoName(url) };
59	    } catch (e) {
60	      console.warn(`  ! skip ${url}: ${e.message.split("\n")[0]}`);
61	      return null;
62	    }
63	  }).filter(Boolean);
64	
65	  // pull edges once per repo
66	  for (const r of repos) {
67	    console.log(`  graphing ${r.name} …`);
68	    r.imports = edges(r.path, ["IMPORTS"]);
69	    r.calls = edges(r.path, ["CALLS", "CONSTRUCTS"]);
70	  }
71	
72	  const total = repos.length;
73	  let callSites = 0;
74	
75	  const steps = spec.steps.map((step) => {
76	    const hitRepos = new Set();
77	    const receipts = [];
78	    const seen = new Set();
79	
80	    if (step.kind === "imports") {
81	      const perModule = new Map(); // module -> Set(repo)
82	      for (const r of repos) {
83	        for (const rec of r.imports) {
84	          const raw = importedModule(rec);
85	          if (!raw || !moduleMatches(raw, step.modules)) continue;
86	          const mod = basePkg(raw);
87	          hitRepos.add(r.name);
88	          if (!perModule.has(mod)) perModule.set(mod, new Set());
89	          perModule.get(mod).add(r.name);
90	          const ev = rec.evidence && rec.evidence[0];
91	          const key = `${r.name}:${ev?.file_path}`;
92	          if (ev?.file_path && !seen.has(key) && receipts.length < 4) {
93	            seen.add(key);
94	            receipts.push(receipt(r.name, r.url, ev.file_path, ev.start_line));
95	          }
96	        }
97	      }
98	      const ranked = [...perModule.entries()]
99	        .sort((a, b) => b[1].size - a[1].size)
100	        .map(([m, s]) => ({ m, n: s.size }));
101	      callSites += ranked.reduce((a, x) => a + x.n, 0);
102	      const installLine = ranked.filter((x) => x.n >= 1).map((x) => x.m).join(" ");
103	      return {
104	        name: step.name,
105	        freq: `${hitRepos.size}/${total}`,
106	        level: hitRepos.size >= Math.ceil(total / 2) ? "high" : "warn",
107	        code: installLine ? `npm i ${installLine}` : step.code,
108	        note:
109	          step.note +
110	          (ranked.length
111	            ? `  Most common: ${ranked.slice(0, 3).map((x) => `${x.m} (${x.n}/${total})`).join(", ")}.`
112	            : ""),
113	        receipts,
114	      };
115	    }
116	
117	    // kind: "calls"
118	    for (const r of repos) {
119	      for (const rec of r.calls) {
120	        const ev = rec.evidence && rec.evidence[0];
121	        const called = ev?.detail || (rec.to_id ? rec.to_id.split(":").pop() : "");
122	        if (!tokenize(called).some((t) => step.symbols.includes(t))) continue;
123	        hitRepos.add(r.name);
124	        const key = `${r.name}:${ev?.file_path}:${ev?.start_line}`;
125	        if (ev?.file_path && !seen.has(key)) {
126	          seen.add(key);
127	          callSites += 1;
128	          if (receipts.length < 5)
129	            receipts.push(receipt(r.name, r.url, ev.file_path, ev.start_line));
130	        }
131	      }
132	    }
133	    return {
134	      name: step.name,
135	      freq: `${hitRepos.size}/${total}`,
136	      level: hitRepos.size >= Math.ceil(total / 2) ? "high" : "warn",
137	      code: step.code,
138	      note: step.note,
139	      receipts,
140	    };
141	  });
142	
143	  return {
144	    id: spec.id,
145	    library: spec.library,
146	    title: spec.title,
147	    emphasis: spec.emphasis,
148	    reposMined: total,
149	    callSites,
150	    runnersUp: spec.runnersUp,
151	    keywords: spec.keywords,
152	    steps,
153	  };
154	}
155	
156	// ---- run ----
157	if (!graphAvailable()) {
158	  console.error("entire-graph not available. Install: entire plugin install graph");
159	  process.exit(1);
160	}
161	
162	const libKey = process.argv[2] || "tiptap";
163	console.log(`\n▶ mining "${libKey}" with entire-graph\n`);
164	const recipe = mine(libKey);
165	
166	let all = [];
167	try {
168	  all = JSON.parse(readFileSync(OUT, "utf8"));
169	} catch {}
170	all = all.filter((r) => r.id !== recipe.id);
171	all.push(recipe);
172	writeFileSync(OUT, JSON.stringify(all, null, 2));
173	
174	console.log(`\n✓ ${recipe.library}: ${recipe.reposMined} repos, ${recipe.callSites} sites`);
175	for (const s of recipe.steps) {
176	  console.log(`  • ${s.name.padEnd(32)} ${s.freq}  (${s.receipts.length} receipts)`);
177	}
178	console.log(`\n→ wrote ${OUT}\n`);
