// Ingest raw entire-graph edges for a goal into the Databricks code_edges Delta
// table, so the recipe can be aggregated in SQL (databricks/derive.sql) across
// MANY repos instead of in-process. This is the "run the graph on Databricks
// compute" scale path: the parse is fanned out here at ingest, the heavy
// cross-repo ranking runs on the warehouse.
//
//   node engine/ingest-databricks.mjs "<end goal>" [--package P] [--repos a,b] [--max-repos 10]
//
// Writes rows into ${CATALOG}.${SCHEMA}.code_edges keyed by the goal slug, then
// deriveRecipe()/derive.sql turn them into a recipe. Discovery + cloning are
// shared with the local generate path (engine/generate.mjs).
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { edges, importedModule } from "./graph.mjs";
import { discoverRepos, clone, repoName, basePkg, isSource, slug } from "./generate.mjs";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");

// minimal .env.local loader (mirrors engine/load-databricks.mjs)
for (const line of (() => {
  try {
    return readFileSync(join(ROOT, ".env.local"), "utf8").split("\n");
  } catch {
    return [];
  }
})()) {
  const m = line.match(/^([A-Z_]+)=(.*)$/);
  if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2];
}

const { DATABRICKS_HOST, DATABRICKS_TOKEN, DATABRICKS_WAREHOUSE_ID } = process.env;
const CATALOG = process.env.DATABRICKS_CATALOG || "workspace";
const SCHEMA = process.env.DATABRICKS_SCHEMA || "recipe";
const TABLE = `${CATALOG}.${SCHEMA}.code_edges`;
const DEFAULT_MAX_REPOS = Number(process.env.MAX_REPOS) || 10;

async function exec(statement) {
  if (!DATABRICKS_HOST || !DATABRICKS_TOKEN || !DATABRICKS_WAREHOUSE_ID) {
    throw new Error("DATABRICKS_HOST / DATABRICKS_TOKEN / DATABRICKS_WAREHOUSE_ID must be set");
  }
  const res = await fetch(`${DATABRICKS_HOST}/api/2.0/sql/statements`, {
    method: "POST",
    headers: { Authorization: `Bearer ${DATABRICKS_TOKEN}`, "Content-Type": "application/json" },
    body: JSON.stringify({ warehouse_id: DATABRICKS_WAREHOUSE_ID, statement, wait_timeout: "50s" }),
  });
  const json = await res.json();
  if (json.status?.state !== "SUCCEEDED") {
    throw new Error(json.status?.error?.message || JSON.stringify(json.status));
  }
  return json;
}

// Spark SQL string literals process backslash escapes, so double backslashes
// (protect embedded JSON / paths) then double single quotes.
const q = (s) => `'${String(s ?? "").replace(/\\/g, "\\\\").replace(/'/g, "''")}'`;
const val = (s) => (s == null ? "NULL" : q(s));
const intVal = (n) => (Number.isFinite(n) ? String(Math.trunc(n)) : "NULL");
const tokenize = (s) => (s || "").split(/[^A-Za-z0-9_$]+/).filter(Boolean);

// ---- args ------------------------------------------------------------------
const argv = process.argv.slice(2);
const flags = { repos: [], maxRepos: DEFAULT_MAX_REPOS };
const words = [];
for (let i = 0; i < argv.length; i++) {
  if (argv[i] === "--repos") flags.repos = (argv[++i] || "").split(",").filter(Boolean);
  else if (argv[i] === "--package") flags.package = argv[++i];
  else if (argv[i] === "--max-repos") flags.maxRepos = Number(argv[++i]) || DEFAULT_MAX_REPOS;
  else words.push(argv[i]);
}
const goal = words.join(" ").trim();
if (!goal) {
  console.error('Usage: node engine/ingest-databricks.mjs "<end goal>" [--package P] [--repos a,b] [--max-repos 10]');
  process.exit(1);
}
const goalSlug = slug(goal);

// ---- discover + clone (fan-out target for the parse) -----------------------
const repoUrls = flags.repos.length
  ? flags.repos
  : discoverRepos(goal, flags.package, flags.maxRepos);
const repos = repoUrls
  .slice(0, flags.maxRepos)
  .map((url) => {
    const path = clone(url);
    return path ? { url, path, name: repoName(url) } : null;
  })
  .filter(Boolean);
if (!repos.length) {
  console.error("no repos could be discovered/cloned for this goal");
  process.exit(1);
}

// ---- extract one row per relevant edge -------------------------------------
const fileCache = new Map();
function sourceLine(repoPath, file, line) {
  if (!file || !line) return null;
  const key = `${repoPath}�${file}`;
  let lines = fileCache.get(key);
  if (lines === undefined) {
    try {
      lines = readFileSync(join(repoPath, file), "utf8").split("\n");
    } catch {
      lines = null;
    }
    fileCache.set(key, lines);
  }
  const l = lines?.[line - 1];
  return l ? l.trim().slice(0, 160) : null;
}

const rows = [];
for (const r of repos) {
  console.error(`  graphing ${r.name} …`);
  const imports = edges(r.path, ["IMPORTS"]).filter((e) => isSource(e.evidence?.[0]?.file_path));
  const calls = edges(r.path, ["CALLS", "CONSTRUCTS"]).filter((e) => isSource(e.evidence?.[0]?.file_path));

  for (const rec of imports) {
    const mod = importedModule(rec);
    if (!mod || mod.startsWith(".") || mod.startsWith("node:")) continue;
    const ev = rec.evidence?.[0];
    rows.push({
      relation: "IMPORTS",
      module: mod,
      base_pkg: basePkg(mod),
      symbol: null,
      repo: r.name,
      repo_url: r.url,
      file: ev?.file_path || null,
      line: ev?.start_line ?? null,
      snippet: null,
    });
  }

  for (const rec of calls) {
    const ev = rec.evidence?.[0];
    const raw = ev?.detail || (rec.to_id ? rec.to_id.split(":").pop() : "");
    const name = tokenize(raw).pop();
    if (!name) continue; // length / case / deny filters are applied in derive.sql
    rows.push({
      relation: rec.type === "CONSTRUCTS" ? "CONSTRUCTS" : "CALLS",
      module: null,
      base_pkg: null,
      symbol: name,
      repo: r.name,
      repo_url: r.url,
      file: ev?.file_path || null,
      line: ev?.start_line ?? null,
      snippet: sourceLine(r.path, ev?.file_path, ev?.start_line),
    });
  }
}

if (!rows.length) {
  console.error("no edges extracted (is entire-graph installed and are these TS/JS repos?)");
  process.exit(1);
}

// ---- load into Databricks --------------------------------------------------
console.error(`\n▶ landing ${rows.length} edge(s) from ${repos.length} repo(s) into ${TABLE} for goal "${goalSlug}"`);
await exec(`DELETE FROM ${TABLE} WHERE goal = ${q(goalSlug)}`);

const COLS = "(goal, repo, repo_url, relation, module, base_pkg, symbol, file, line, snippet, mined_at)";
const CHUNK = 200;
for (let i = 0; i < rows.length; i += CHUNK) {
  const tuples = rows.slice(i, i + CHUNK).map((row) =>
    `(${q(goalSlug)}, ${q(row.repo)}, ${q(row.repo_url)}, ${q(row.relation)}, ` +
    `${val(row.module)}, ${val(row.base_pkg)}, ${val(row.symbol)}, ${val(row.file)}, ` +
    `${intVal(row.line)}, ${val(row.snippet)}, current_timestamp())`
  );
  await exec(`INSERT INTO ${TABLE} ${COLS} VALUES ${tuples.join(", ")}`);
  console.error(`  loaded ${Math.min(i + CHUNK, rows.length)}/${rows.length}`);
}

const summary = await exec(
  `SELECT count(*), count(DISTINCT repo) FROM ${TABLE} WHERE goal = ${q(goalSlug)}`
);
const [edgeCount, repoCount] = summary.result?.data_array?.[0] || [];
console.error(`done. goal "${goalSlug}": ${edgeCount} edges across ${repoCount} repos.`);
// stdout is machine-readable so the API route can capture the mined repo count
console.log(JSON.stringify({ goal: goalSlug, repos: Number(repoCount) || repos.length, edges: Number(edgeCount) || rows.length }));

